const SummarizeBillingPayments = `-- name: SummarizeBillingPayments :many
SELECT
    state,
    operation,
    network,
    asset,
    count(*)::numeric AS payment_count,
    COALESCE(sum(amount_atomic), 0)::numeric AS amount_atomic
FROM billing_payments
WHERE chain_id = $1::numeric
  AND created_at >= $2
  AND created_at < $3
  AND (
      $4::text IS NULL
      OR state = $4::text
  )
  AND (
      $5::text IS NULL
      OR operation = $5::text
  )
  AND (
      $6::text IS NULL
      OR network = $6::text
  )
  AND (
      $7::bytea IS NULL
      OR asset = $7::bytea
  )
GROUP BY state, operation, network, asset
ORDER BY state, operation, network, asset
`

type SummarizeBillingPaymentsParams struct {
	ChainID   pgtype.Numeric     `db:"chain_id" json:"chain_id"`
	FromTime  pgtype.Timestamptz `db:"from_time" json:"from_time"`
	ToTime    pgtype.Timestamptz `db:"to_time" json:"to_time"`
	State     *string            `db:"state" json:"state"`
	Operation *string            `db:"operation" json:"operation"`
	Network   *string            `db:"network" json:"network"`
	Asset     []byte             `db:"asset" json:"asset"`
}

type SummarizeBillingPaymentsRow struct {
	State        string         `db:"state" json:"state"`
	Operation    string         `db:"operation" json:"operation"`
	Network      string         `db:"network" json:"network"`
	Asset        []byte         `db:"asset" json:"asset"`
	PaymentCount pgtype.Numeric `db:"payment_count" json:"payment_count"`
	AmountAtomic pgtype.Numeric `db:"amount_atomic" json:"amount_atomic"`
}

func (q *Queries) SummarizeBillingPayments(ctx context.Context, arg SummarizeBillingPaymentsParams) ([]SummarizeBillingPaymentsRow, error) {
	rows, err := q.db.Query(ctx, SummarizeBillingPayments,
		arg.ChainID,
		arg.FromTime,
		arg.ToTime,
		arg.State,
		arg.Operation,
		arg.Network,
		arg.Asset,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummarizeBillingPaymentsRow{}
	for rows.Next() {
		var i SummarizeBillingPaymentsRow
		if err := rows.Scan(
			&i.State,
			&i.Operation,
			&i.Network,
			&i.Asset,
			&i.PaymentCount,
			&i.AmountAtomic,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
